import React, { useState, useEffect } from "react";
import { useParams, useNavigate, useSearchParams } from "react-router-dom";
import axios from "axios";
import "../components/css/petshop.css";

function PetShop() {
  const { clinicId } = useParams();
  const [searchParams] = useSearchParams();
  const ownerId = searchParams.get("ownerId");
  const isGuest = searchParams.get("guest");
  const [step, setStep] = useState(1);
  const [selectedDate, setSelectedDate] = useState("");
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [petName, setPetName] = useState("");
  const [petType, setPetType] = useState("");
  const [petBreed, setPetBreed] = useState("");
  const [petAge, setPetAge] = useState("");
  const [petGender, setPetGender] = useState("");
  const [services, setServices] = useState([]);
  const [pets, setPets] = useState([]);
  const [selectedService, setSelectedService] = useState("");
  const [clinic, setClinic] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchClinicData = async () => {
      if (!clinicId) {
        console.error("Clinic ID is undefined");
        return;
      }
      try {
        const clinicResponse = await axios.get(`http://localhost:5000/api/clinics/${clinicId}`);
        setClinic(clinicResponse.data);

        const servicesResponse = await axios.get(`http://localhost:5000/api/services/clinic/${clinicId}`);
        setServices(servicesResponse.data);
      } catch (error) {
        console.error("Error fetching clinic or services:", error);
      }
    };

    const fetchOwnerData = async () => {
      if (ownerId && !isGuest) {
        try {
          const token = localStorage.getItem("token");
          if (token) {
            const ownerResponse = await axios.get(`http://localhost:5000/api/owners/${ownerId}`, {
              headers: { "Authorization": `Bearer ${token}` }
            });
            setName(`${ownerResponse.data.firstname} ${ownerResponse.data.lastname}`);
            setEmail(ownerResponse.data.email);

            const fetchPets = async () => {
              try {
                const response = await fetch(`http://10.10.79.169:5000/api/pets`, {
                  method: "GET",
                  headers: {
                    "Authorization": `Bearer ${token}`,
                    "Content-Type": "application/json",
                  },
                });

                if (!response.ok) {
                  throw new Error("Failed to fetch pets");
                }

                const data = await response.json();
                const ownerPets = data.filter((p) => p.owner_id === ownerId);
                setPets(ownerPets);
              } catch (error) {
                console.error("Error fetching pets:", error);
              }
            };

            fetchPets();
          }
        } catch (error) {
          console.error("Error fetching owner or pets:", error);
        }
      }
    };

    fetchClinicData();
    fetchOwnerData();
  }, [clinicId, ownerId, isGuest]);

  const handleSubmit = async () => {
    if (!selectedDate || !selectedService || !name || !email || !petName || !petType || !petGender) {
      alert("Please fill out all required fields!");
      return;
    }

    try {
      let finalOwnerId = ownerId;
      if (!ownerId || isGuest) {
        const ownerResponse = await axios.post("http://localhost:5000/api/owners/register", {
          firstname: name.split(" ")[0],
          lastname: name.split(" ")[1] || "",
          email,
          isGuest: true,
        });
        finalOwnerId = ownerResponse.data._id;
      }

      const petResponse = await axios.post("http://localhost:5000/api/pets/register", {
        owner_id: finalOwnerId,
        name: petName,
        type: petType,
        breed: petBreed,
        age: petAge,
        gender: petGender,
      });

      const appointmentData = {
        clinic_id: clinicId,
        date: selectedDate,
        owner_id: finalOwnerId,
        pet_id: petResponse.data._id,
        service_id: selectedService,
        notes: "Some notes",
      };

      await axios.post("http://localhost:5000/api/appointments/create", appointmentData);
      alert("Appointment booked successfully!");
      navigate(`/appointments`);
    } catch (error) {
      console.error("Error creating appointment:", error);
      alert("An error occurred while booking the appointment.");
    }
  };

  return (
    <div className="page-container">
      <div className="petshop-container">
        {clinic && (
          <div className="shop-info">
            <img src={`http://localhost:5000${clinic.logo}`} className="shop-logo-book" />
            <h2>{clinic.name}</h2>
            <p>{clinic.description}</p>
          </div>
        )}

        <div className="form-container">
          {step === 1 && (
            <>
              <h3>Welcome!</h3>
              <p>To book a service, please provide your details.</p>
              <button className="action-button" onClick={() => setStep(2)}>Continue</button>
            </>
          )}

          {step === 2 && (
            <>
              <h3>Appointment Details</h3>
              <input type="date" value={selectedDate} onChange={(e) => setSelectedDate(e.target.value)} />
              <select value={selectedService} onChange={(e) => setSelectedService(e.target.value)}>
                <option value="">Select Service</option>
                {services.map((service) => (
                  <option key={service._id} value={service._id}>{service.name}</option>
                ))}
              </select>
              <button className="action-button" onClick={() => setStep(3)}>Continue</button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

export default PetShop;
